import{_ as a,H as t,f as i,i as l}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"加餐 | 软件设计文档示例模板","description":"","frontmatter":{},"headers":[{"level":2,"title":"1 设计概述","slug":"_1-设计概述","link":"#_1-设计概述","children":[{"level":3,"title":"1.1 功能概述","slug":"_1-1-功能概述","link":"#_1-1-功能概述","children":[]},{"level":3,"title":"1.2 非功能约束","slug":"_1-2-非功能约束","link":"#_1-2-非功能约束","children":[]}]},{"level":2,"title":"2 系统部署图与整体设计","slug":"_2-系统部署图与整体设计","link":"#_2-系统部署图与整体设计","children":[{"level":3,"title":"2.1 系统部署图","slug":"_2-1-系统部署图","link":"#_2-1-系统部署图","children":[]},{"level":3,"title":"2.2 下单场景子系统序列图","slug":"_2-2-下单场景子系统序列图","link":"#_2-2-下单场景子系统序列图","children":[]},{"level":3,"title":"2.3 退款场景子系统序列图","slug":"_2-3-退款场景子系统序列图","link":"#_2-3-退款场景子系统序列图","children":[]},{"level":3,"title":"2.4 退款场景子系统活动图","slug":"_2-4-退款场景子系统活动图","link":"#_2-4-退款场景子系统活动图","children":[]}]},{"level":2,"title":"3 子系统1设计","slug":"_3-子系统1设计","link":"#_3-子系统1设计","children":[{"level":3,"title":"3.1 子系统1组件图","slug":"_3-1-子系统1组件图","link":"#_3-1-子系统1组件图","children":[]},{"level":3,"title":"3.2 组件1设计","slug":"_3-2-组件1设计","link":"#_3-2-组件1设计","children":[]},{"level":3,"title":"3.3 组件2设计","slug":"_3-3-组件2设计","link":"#_3-3-组件2设计","children":[]}]},{"level":2,"title":"4 子系统2设计","slug":"_4-子系统2设计","link":"#_4-子系统2设计","children":[]}],"relativePath":"后端技术面试38讲/加餐-软件设计文档示例模板.md","filePath":"后端技术面试38讲/加餐-软件设计文档示例模板.md","lastUpdated":1779819087000}'),n={name:"后端技术面试38讲/加餐-软件设计文档示例模板.md"};function s(r,e,o,h,E,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="加餐-软件设计文档示例模板" tabindex="-1">加餐 | 软件设计文档示例模板 <a class="header-anchor" href="#加餐-软件设计文档示例模板" aria-label="Permalink to &quot;加餐 | 软件设计文档示例模板&quot;">​</a></h1><p>在 <a href="https://time.geekbang.org/column/article/175529" target="_blank" rel="noreferrer">第9篇文章</a> 中，我讲了每种UML模型图的画法，以及这些画法分别适用于什么样的设计阶段，我们也可以将不同阶段输出的模型图放在一个文档中，对每张模型图配以适当的文字说明，构成一篇设计文档。</p><p>对于规模不太大的软件系统，我们可以将概要设计文档和详细设计文档合并成一个设计文档。这一篇文章中，我会展现一个设计文档示例模板，你可以参考这个模板编写你的设计文档。</p><p>文档开头是设计概述，简单描述业务场景要解决的核心问题领域是什么。至于业务场景，应该在专门的需求文档中描述，但是在设计文档中，必须要再简单描述一下，以保证设计文档的完整性，这样，即使脱离需求文档，阅读者也能理解主要的设计。</p><p>此外，在设计概述中，还需要描述设计的非功能约束，比如关于性能、可用性、维护性、安全性，甚至开发和部署成本方面的设计目标。</p><p>然后就是具体的设计了，第一张设计图应该是部署图，通过部署图描述系统整个物理模型蓝图，包括未来系统长什么样。</p><p>如果系统中包含几个子系统，那么还需要描述子系统间的关系，可以通过子系统序列图，子系统活动图进行描述。</p><p>子系统内部的最顶层设计就是组件图，描述子系统由哪些组件组成，不同场景中，组件之间的调用序列图是什么样的。</p><p>每个组件内部，需要用类图进行建模描述，对于不同场景，用时序图描述类之间的动态调用关系，对于有复杂状态的类，用状态图描述其状态转换。</p><p>具体示例模板如下：</p><h2 id="_1-设计概述" tabindex="-1">1 设计概述 <a class="header-anchor" href="#_1-设计概述" aria-label="Permalink to &quot;1 设计概述&quot;">​</a></h2><p>……系统是一个……的系统，是公司……战略的核心系统，承担着公司……的目标任务。</p><h3 id="_1-1-功能概述" tabindex="-1">1.1 功能概述 <a class="header-anchor" href="#_1-1-功能概述" aria-label="Permalink to &quot;1.1 功能概述&quot;">​</a></h3><p>系统主要功能包括……，使用者包括……。</p><h3 id="_1-2-非功能约束" tabindex="-1">1.2 非功能约束 <a class="header-anchor" href="#_1-2-非功能约束" aria-label="Permalink to &quot;1.2 非功能约束&quot;">​</a></h3><p>……系统未来预计一年用户量达到……，日订单量达到……，日PV达到……，图片数量达到 ……。</p><ol><li>查询性能目标：平均响应时间&lt;300ms，95%响应时间&lt;500ms，单机TPS&gt;100；</li><li>下单性能目标：平均响应时间&lt;800ms，95%响应时间&lt;1000ms，单机TPS&gt;30；</li><li>……性能目标：平均响应时间&lt;800ms，95%响应时间&lt;1000ms，单机TPS&gt;30；</li><li>系统核心功能可用性目标：&gt;99.97%；</li><li>系统安全性目标：系统可拦截…… 、……、……攻击，密码数据散列加密，客户端数据HTTPS加密，外部系统间通信对称加密；</li><li>数据持久化目标：&gt;99.99999%。</li></ol><h2 id="_2-系统部署图与整体设计" tabindex="-1">2 系统部署图与整体设计 <a class="header-anchor" href="#_2-系统部署图与整体设计" aria-label="Permalink to &quot;2 系统部署图与整体设计&quot;">​</a></h2><p>系统上线时预计部署……台物理机，……个子系统，和公司……系统交互，和外部第三方……个系统交互。</p><h3 id="_2-1-系统部署图" tabindex="-1">2.1 系统部署图 <a class="header-anchor" href="#_2-1-系统部署图" aria-label="Permalink to &quot;2.1 系统部署图&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/4bb2e603dc9ed6ab9700f29fa5cbb5cb.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/4bb2e603dc9ed6ab9700f29fa5cbb5cb.png" alt=""></a></p><p>子系统1的功能职责为……，部署……台服务器，依赖……和……子系统，实现 ……功能。</p><p>子系统2参照子系统1来写。</p><h3 id="_2-2-下单场景子系统序列图" tabindex="-1">2.2 下单场景子系统序列图 <a class="header-anchor" href="#_2-2-下单场景子系统序列图" aria-label="Permalink to &quot;2.2 下单场景子系统序列图&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/4022d74c2923e8bf5adc013788e05fac.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/4022d74c2923e8bf5adc013788e05fac.png" alt=""></a></p><ol><li>下单时，子系统先发送……消息到子系统3，子系统3需要执行……完成……处理，然后发送……消息到财务系统，消息中包含……数据。</li><li>收到……的处理结果……后，子系统1发送……消息到……子系统2……。</li></ol><h3 id="_2-3-退款场景子系统序列图" tabindex="-1">2.3 退款场景子系统序列图 <a class="header-anchor" href="#_2-3-退款场景子系统序列图" aria-label="Permalink to &quot;2.3 退款场景子系统序列图&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/4022d74c2923e8bf5adc013788e05fac.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/4022d74c2923e8bf5adc013788e05fac.png" alt=""></a></p><ol><li>退款子系统先发送……消息到子系统3，子系统3需要执行……完成……处理，然后发送……消息到财务系统，消息中包含……数据。</li><li>收到……的处理结果……后，子系统1发送……消息到……子系统2……。</li></ol><h3 id="_2-4-退款场景子系统活动图" tabindex="-1">2.4 退款场景子系统活动图 <a class="header-anchor" href="#_2-4-退款场景子系统活动图" aria-label="Permalink to &quot;2.4 退款场景子系统活动图&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/375ef48e2f806f42460b1beba71d2ae1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/375ef48e2f806f42460b1beba71d2ae1.png" alt=""></a></p><p>如图所示：</p><ol><li>退款开始时，子系统1处理XXX，然后判断m的状态，如果m为真，请求子系统3处理ZZZ，如果m为假，子系统继续处理ZZZ并结束。</li><li>子系统3处理ZZZ后，一方面继续处理XYZ，一方面将……消息发送给财务通进行AAA处理。</li><li>子系统在处理完XYZ后，返回子系统继续梳理YYY，然后退款处理结束。</li></ol><h2 id="_3-子系统1设计" tabindex="-1">3 子系统1设计 <a class="header-anchor" href="#_3-子系统1设计" aria-label="Permalink to &quot;3 子系统1设计&quot;">​</a></h2><p>子系统1的主要功能职责是……，其中主要包含了……组件。</p><h3 id="_3-1-子系统1组件图" tabindex="-1">3.1 子系统1组件图 <a class="header-anchor" href="#_3-1-子系统1组件图" aria-label="Permalink to &quot;3.1 子系统1组件图&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/53440aeb1890d9de2234e7392b7fbc51.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/53440aeb1890d9de2234e7392b7fbc51.png" alt=""></a></p><p>子系统1包含6个组件：</p><p>组件1的功能主要是……，需要依赖组件2完成……，是子系统1的核心组件，用户……请求主要通过组件1完成。</p><p>同样的，组件2也可以参照组件1来这样写。</p><h4 id="_3-1-1-场景a组件序列图" tabindex="-1">3.1.1 场景A组件序列图 <a class="header-anchor" href="#_3-1-1-场景a组件序列图" aria-label="Permalink to &quot;3.1.1 场景A组件序列图&quot;">​</a></h4><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/15b121ced550eca4913773fc14dcaf89.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/15b121ced550eca4913773fc14dcaf89.png" alt=""></a></p><p>对于场景A，首先组件1收到用户消息CCC，然后组件1调用组件2的XXX方法……。</p><h4 id="_3-1-2-场景b组件活动图" tabindex="-1">3.1.2 场景B组件活动图 <a class="header-anchor" href="#_3-1-2-场景b组件活动图" aria-label="Permalink to &quot;3.1.2 场景B组件活动图&quot;">​</a></h4><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/c37566e9d6709b5aa75d9fdb7c1a4513.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/c37566e9d6709b5aa75d9fdb7c1a4513.png" alt=""></a></p><p>在场景B中，首先组件收到……消息，开始处理……，然后判断……，如果为true，那么……，如果为false，那么……。</p><h3 id="_3-2-组件1设计" tabindex="-1">3.2 组件1设计 <a class="header-anchor" href="#_3-2-组件1设计" aria-label="Permalink to &quot;3.2 组件1设计&quot;">​</a></h3><p>组件1的主要功能职责是……，其中主要包含了……类。</p><h4 id="_3-2-1-组件1-类图" tabindex="-1">3.2.1 组件1 类图 <a class="header-anchor" href="#_3-2-1-组件1-类图" aria-label="Permalink to &quot;3.2.1 组件1 类图&quot;">​</a></h4><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/e299191932e2f306dceed924b2915b4d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/e299191932e2f306dceed924b2915b4d.png" alt=""></a></p><p>Class1实现接口Interface1，主要功能是……，Class1聚合了Class2和Class3，共同对外提供……服务，Class1依赖Class4实现……功能，Class4……。</p><h4 id="_3-2-2-场景a-类序列图" tabindex="-1">3.2.2 场景A 类序列图 <a class="header-anchor" href="#_3-2-2-场景a-类序列图" aria-label="Permalink to &quot;3.2.2 场景A 类序列图&quot;">​</a></h4><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/6b7c8d72357d1d7a26159a78378ed602.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/6b7c8d72357d1d7a26159a78378ed602.png" alt=""></a></p><p>在场景A中，当外部应用调用类1的create方法时，类1……。</p><h4 id="_3-2-3-对象1状态图" tabindex="-1">3.2.3 对象1状态图 <a class="header-anchor" href="#_3-2-3-对象1状态图" aria-label="Permalink to &quot;3.2.3 对象1状态图&quot;">​</a></h4><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/bc2c158c13cfb129fba57f1b60aadc2e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E6%8A%80%E6%9C%AF%E9%9D%A2%E8%AF%9538%E8%AE%B2/images/176947/bc2c158c13cfb129fba57f1b60aadc2e.png" alt=""></a></p><p>对象1运行时有4种状态，初始状态是状态1，当条件1满足是，状态1转换为状态2，当条件3满足时，状态2转换为状态4……。</p><h3 id="_3-3-组件2设计" tabindex="-1">3.3 组件2设计 <a class="header-anchor" href="#_3-3-组件2设计" aria-label="Permalink to &quot;3.3 组件2设计&quot;">​</a></h3><p>重复上面的格式。</p><h2 id="_4-子系统2设计" tabindex="-1">4 子系统2设计 <a class="header-anchor" href="#_4-子系统2设计" aria-label="Permalink to &quot;4 子系统2设计&quot;">​</a></h2><p>重复上面的格式。</p>',61)])])}const p=a(n,[["render",s]]);export{A as __pageData,p as default};
